(()=>{const root=document.documentElement;const clamp=x=>Math.max(0,Math.min(1,x));const scenes=['A life is made of the threads we choose to follow.','The circle is open. So are the questions.','A small act of care travels farther than I can see.','There is still light in what I have not become.'];let scene=-1;const baseSelect=selectTheme;selectTheme=function(n){baseSelect(n);if(scene!==selected){scene=selected;$('#sceneIndex').textContent=`0${selected+1} / ${reflections[selected].name.toUpperCase()}`;const p=$('#sceneLine');p.textContent=scenes[selected];p.classList.remove('switching');void p.offsetWidth;p.classList.add('switching');document.querySelectorAll('[data-scroll-scene]').forEach((b,i)=>b.classList.toggle('on',i===selected));animateTitle($('#chapterTitle'))}};function animateTitle(el){if(reduced)return;const words=el.textContent.split(' ');el.replaceChildren(...words.flatMap((word,i)=>{const outer=document.createElement('span');outer.className='title-word';const inner=document.createElement('span');inner.textContent=word;inner.style.setProperty('--word-i',i);outer.append(inner);return i?[document.createTextNode(' '),outer]:[outer]}))}document.querySelectorAll('[data-scroll-scene]').forEach(b=>b.onclick=()=>{manualTheme=false;const n=+b.dataset.scrollScene;selectTheme(n);const hero=$('.hero');window.scrollTo({top:hero.offsetTop+n/(reflections.length-1)*(hero.offsetHeight-innerHeight),behavior:reduced?'instant':'smooth'})});
const revealElements=document.querySelectorAll('.chapter-tabs,article,.small-cross,.artist .eyebrow,.artist h2,.artist-text>p,.credits,footer');if(!reduced){root.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('seen');observer.unobserve(entry.target)}},{threshold:.12});revealElements.forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',`${i%3*70}ms`);observer.observe(el)})}
let pending=false;function update(){pending=false;const sy=scrollY,vh=innerHeight,hero=$('.hero'),verse=$('.word-journey'),ch=$('.chapters'),artist=$('.artist');root.style.setProperty('--page-progress',clamp(sy/(document.documentElement.scrollHeight-vh)));const progress=clamp((sy-hero.offsetTop)/(hero.offsetHeight-vh));root.style.setProperty('--hero-progress',progress);root.style.setProperty('--verse-progress',clamp((sy-verse.offsetTop)/Math.max(1,(verse.offsetHeight-vh)*.58)));root.style.setProperty('--chapter-progress',clamp((sy+vh*.7-ch.offsetTop)/ch.offsetHeight));root.style.setProperty('--artist-progress',clamp((sy+vh-artist.offsetTop)/artist.offsetHeight));}function queue(){if(!pending){pending=true;requestAnimationFrame(update)}}addEventListener('scroll',queue,{passive:true});addEventListener('resize',queue);addEventListener('load',()=>{resize();queue()});document.fonts.ready.then(()=>{resize();queue()});selectTheme(selected);queue();})();
